package cmd

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// The help audit's two checked-in artifacts (#1050): the rubric every child
// audit judges a help page against, and the command-tree inventory every child
// records its result in. The inventory is generated by scripts/gen-help-inventory.sh
// from the built binary; the full tree-vs-file comparison is `make
// help-inventory-check`. This test holds what must stay true of the files
// themselves, and one cheap tie to the live tree: every top-level command has a
// row, so a new top-level command cannot ship unaudited and unlisted.

func readDoc(t *testing.T, rel string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", rel))
	if err != nil {
		t.Fatalf("%s must exist: %v", rel, err)
	}
	return string(b)
}

type inventoryRow struct {
	path, aliases, generated, examples, child, evaluator, result, finding string
	section                                                               string
}

var (
	sectionStart = regexp.MustCompile(`^<!-- group:(\S+) start -->$`)
	sectionEnd   = regexp.MustCompile(`^<!-- group:(\S+) end -->$`)
)

func parseInventory(t *testing.T, doc string) []inventoryRow {
	t.Helper()
	var rows []inventoryRow
	open := ""
	for _, line := range strings.Split(doc, "\n") {
		if m := sectionStart.FindStringSubmatch(line); m != nil {
			if open != "" {
				t.Fatalf("section %s opened inside section %s", m[1], open)
			}
			open = m[1]
			continue
		}
		if m := sectionEnd.FindStringSubmatch(line); m != nil {
			if open != m[1] {
				t.Fatalf("section end %s does not close open section %q", m[1], open)
			}
			open = ""
			continue
		}
		if !strings.HasPrefix(line, "| `") {
			continue
		}
		if open == "" {
			t.Fatalf("row outside any group section: %s", line)
		}
		cells := strings.Split(strings.TrimSuffix(strings.TrimPrefix(line, "| "), " |"), " | ")
		if len(cells) != 8 {
			t.Fatalf("row has %d cells, want 8: %s", len(cells), line)
		}
		for i := range cells {
			cells[i] = strings.TrimSpace(cells[i])
		}
		rows = append(rows, inventoryRow{
			path: strings.Trim(cells[0], "`"), aliases: cells[1], generated: cells[2], examples: cells[3],
			child: cells[4], evaluator: cells[5], result: cells[6], finding: cells[7], section: open,
		})
	}
	if open != "" {
		t.Fatalf("section %s is never closed", open)
	}
	return rows
}

func TestHelpInventoryFileShape(t *testing.T) {
	doc := readDoc(t, "docs/help-inventory.md")
	if !regexp.MustCompile(`(?m)^Pinned commit: [0-9a-f]{7,40}$`).MatchString(doc) {
		t.Errorf("inventory must state its pinned commit SHA as `Pinned commit: <sha>`")
	}
	if !regexp.MustCompile(`(?m)^CLI version: \S+`).MatchString(doc) {
		t.Errorf("inventory must state the CLI version string it was read from")
	}
	if !strings.Contains(doc, "hidden and deprecated commands are not inventoried") {
		t.Errorf("inventory must state that hidden and deprecated commands are not inventoried")
	}
	rows := parseInventory(t, doc)
	if len(rows) == 0 {
		t.Fatal("inventory has no rows")
	}
	seen := map[string]bool{}
	for _, r := range rows {
		if seen[r.path] {
			t.Errorf("duplicate inventory row %q", r.path)
		}
		seen[r.path] = true
		switch r.result {
		case "unread", "fail":
		case "pass":
			if r.evaluator == "" {
				t.Errorf("row %q is pass with no named evaluator", r.path)
			}
		default:
			t.Errorf("row %q result %q: must be one of unread|pass|fail", r.path, r.result)
		}
		if r.examples != "y" && r.examples != "n" {
			t.Errorf("row %q has-examples %q: must be y or n", r.path, r.examples)
		}
	}
	if !seen["(root)"] {
		t.Errorf("inventory must carry a (root) row for `hadron --help` and the global flags")
	}
}

func TestHelpInventoryCoversEveryTopLevelCommand(t *testing.T) {
	f, _ := testFactory(t)
	root := NewRootCmd(f)
	// help and completion are added lazily at execute time; the inventory lists
	// them as the pages a user reads.
	root.InitDefaultHelpCmd()
	root.InitDefaultCompletionCmd()
	have := map[string]bool{}
	for _, r := range parseInventory(t, readDoc(t, "docs/help-inventory.md")) {
		have[r.path] = true
	}
	n := 0
	for _, c := range root.Commands() {
		if c.Hidden || c.Deprecated != "" {
			continue
		}
		n++
		if !have[c.Name()] {
			t.Errorf("top-level command %q has no inventory row: run `make help-inventory`", c.Name())
		}
	}
	if n < 30 {
		t.Fatalf("walked only %d top-level commands; the test is not seeing the real tree", n)
	}
}

func TestHelpRubricDefinesTheContract(t *testing.T) {
	doc := readDoc(t, "docs/help-review-rubric.md")
	for _, want := range []string{
		"unread", "pass", "fail", // closed result vocabulary
		"P1", "P2", "P3", // severity scale
		"confusing wording", "suggested revision", "missing supported workflow", // per-page format
		"prerequisites", "defaults", "recover", // the questions a page must answer
		"jargon", "assumed context", "org", "example", // the flags to raise
		"evaluator", "goals list", "not the author", // evaluator packet
	} {
		if !strings.Contains(strings.ToLower(doc), strings.ToLower(want)) {
			t.Errorf("rubric does not mention %q", want)
		}
	}
}

func TestContributionWorkflowLinksTheRubric(t *testing.T) {
	doc := readDoc(t, "CLAUDE.md")
	if !strings.Contains(doc, "docs/help-review-rubric.md") {
		t.Errorf("CLAUDE.md must link docs/help-review-rubric.md from the review workflow")
	}
}
